import pandas as pd

def _create_input_df_from_user(model_columns_list, gender, age, country, city, os_name):

    input_data = pd.DataFrame(0, index=[0], columns=model_columns_list)

    if 'gender' in input_data.columns:
        input_data.loc[0, 'gender'] = gender
    if 'age' in input_data.columns:
        input_data.loc[0, 'age'] = age

    country_col = f"country_{country}"
    if country_col in input_data.columns:
        input_data.loc[0, country_col] = 1

    city_col = f"city_{city}"
    if city_col in input_data.columns:
        input_data.loc[0, city_col] = 1

    os_col = f"os_{os_name}"
    if os_col in input_data.columns:
        input_data.loc[0, os_col] = 1

    return input_data

